head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods10020";
scwin.setCorpInfo = null;
scwin.emailCheck = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.setCorpInfo = scwin.tx_setCorpInfo;
        scwin.emailCheck = scwin.tx_emailCheck;
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods10020.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openComPop_onclick
 * @description 「회사명」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openComPop_onclick = async function(e){
    try {
        await scwin.openComPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10020.btn_openComPop_onclick' }); }
};

/**
 * @method
 * @name btn_ChkDuplicate_onclick
 * @description 「아이디 중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ChkDuplicate_onclick = async function(e){
    try {
        await scwin.tx_fn_ChkDuplicate()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10020.btn_ChkDuplicate_onclick' }); }
};

/**
 * @method
 * @name btn_emailCheck_onclick
 * @description 「E-mail 중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_emailCheck_onclick = function(e){
    try {
        scwin.emailCheck()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10020.btn_emailCheck_onclick' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.sendForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods10020.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancel_onclick = function(e){
    try {
        scwin.cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods10020.btn_cancel_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_sendForm
 * @description send Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendForm = async function () {
    const sbmOptions = {
        id: "tx_sendForm",
        method: "post",
        action: "/account/disclsUserInfo.do?method=disclsUserInfo",
        ref: "dma_sendFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_setCorpInfo
 * @description set Corp Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_setCorpInfo = async function () {
    const sbmOptions = {
        id: "tx_setCorpInfo",
        method: "post",
        action: "/account/registProc.do",
        ref: "dma_setCorpInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ChkDuplicate
 * @description Chk Duplicate 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ChkDuplicate = async function () {
    const sbmOptions = {
        id: "tx_fn_ChkDuplicate",
        method: "post",
        action: "/account/registProc.do",
        ref: "dma_ChkDuplicateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_emailCheck
 * @description email Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_emailCheck = async function () {
    const sbmOptions = {
        id: "tx_emailCheck",
        method: "post",
        action: "/account/registProc.do",
        ref: "dma_emailCheckReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openComPop
 * @description open Com Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openComPop = async function () {
    const url = '/jldfil00033/jldfil00033.xml';
    const option = "width=560,height=780,resizable=no,scrollbars=no,toolbar=no";
    scwin.setCorpInfo_recv(await $c.win.openPopup(url, String((typeof option !== 'undefined' ? option : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); let k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "_blank", width: "560", height: "780", resizable: false, scrollbars: false, type: "pageFramePopup" }, { id: '' }) : { id: "_blank", width: "560", height: "780", resizable: false, scrollbars: false, type: "pageFramePopup" }), { method: "searchSubcomForm" }));
    return;
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    confirmF("회원가입 신청을 취소 하시겠습니까?", async function() {
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/main.do). 전환 대상 화면이 확정되면 연결됩니다.');
    });
};

/**
 * @method
 * @name sendForm
 * @description send Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendForm = async function () {
    const frm = (document.frmReg || { elements: [] });
    const corpName = $c.util.getComponent('ipt_corpName');
    const usrIdObj = $c.util.getComponent('ipt_usrId_2');
    const corpUsrNm = $c.util.getComponent('ipt_corpUsrNm_2');
    const usrBelngDepNm = $c.util.getComponent('ipt_usrBelngDepNm');
    const jobtitlNm = $c.util.getComponent('ipt_jobtitlNm');
    if (await $c.fil.checkRequired(corpName)) {
        return;
    }
    if (await $c.fil.checkRequired(usrIdObj)) {
        return;
    }
    if (await $c.fil.checkRequired(corpUsrNm)) {
        return;
    }
    if (await $c.fil.checkRequired(usrBelngDepNm)) {
        return;
    }
    if (await $c.fil.checkRequired(jobtitlNm)) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo1'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo2'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo1'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo2'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email1'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if ($c.util.getComponent('ipt_idYn').getValue() !== usrIdObj.getValue()) {
        await alertE("아이디 중복여부를 확인하시기 바랍니다.");
        return;
    }
    $c.util.getComponent('dma_sendFormReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    if ($c.util.getComponent('ipt_emailUseYn').getValue() !== $c.util.getComponent('dma_sendFormReq').get('email')) {
        await alertE("이메일 중복여부를 확인하시기 바랍니다.");
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_telNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await alertE('유선전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await alertE('휴대전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_faxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await alertE('FAX는 숫자만 입력하십시오.');
        return;
    }
    if (!$("#check1").is(":checked")) {
        await alertE("개인정보 처리방침 동의 여부를 확인하시기 바랍니다.");
        check1.focus();
        return;
    }
    if (!$("#check2").is(":checked")) {
        await alertE("개인정보 수집 및 이용 동의 여부를 확인하시기 바랍니다.");
        check2.focus();
        return;
    }
    confirmF("회원가입 신청을 하시겠습니까?", function() {
            $c.util.getComponent('dma_sendFormReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue() + '-' + $c.util.getComponent('ipt_telNo2').getValue() + '-' + $c.util.getComponent('ipt_telNo3').getValue());
            $c.util.getComponent('dma_sendFormReq').set('cellphoneNo', $c.util.getComponent('ipt_cellphoneNo1').getValue() + '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue() + '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
            $c.util.getComponent('dma_sendFormReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue() + '-' + $c.util.getComponent('ipt_faxNo2').getValue() + '-' + $c.util.getComponent('ipt_faxNo3').getValue());
            blockLoading("처리중입니다.");
            $.ajax({ type: "POST", url: "/account/registProc.do?method=registerProcess", data: $("#frmReg").serialize(), dataType: 'JSON', success: async function(data) {
                        if (data.result.regSuc === 1) {
                            $c.util.getComponent("dma_sendFormReq").set("corpUsrNm", data.result.corpUsrNm);
                            $c.util.getComponent('dma_sendFormReq').set('corpNm', data.result.corpNm);
                            $c.util.getComponent("ipt_usrId_2").setValue(data.result.usrId);
                            $c.util.getComponent("ipt_isurCd_2").setValue(data.result.isurCd);
                            $c.util.getComponent('dma_sendFormReq').set('regSuc', data.result.regSuc);
                            $c.util.getComponent('dma_sendFormReq').set('mailSuc', data.result.mailSuc);
                            await scwin.tx_sendForm();
                        } else {
                            ($.fn && $.fn.dialog ? $("#loading").dialog("close") : undefined);
                            await alertE("회원가입 신청에 실패하였습니다. \n시스템 담당자에게 문의하시기 바랍니다.");
                        }
                    }, error: async function(request, status, error) {
                        ($.fn && $.fn.dialog ? $("#loading").dialog("close") : undefined);
                        await alertE("회원가입 신청에 실패하였습니다. \n시스템 담당자에게 문의하시기 바랍니다.");
                        return;
                    } });
    });
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
